<?php use App\Core\View;$rate=static fn($a,$v)=>$v>0?number_format($a/$v*100,1).'%':'0.0%';$delta=static fn($a,$b)=>$b>0?number_format(($a-$b)/$b*100,1).'%':($a>0?'신규':'0.0%'); ?>
<div class="page-header"><div><div class="eyebrow">Invitation analytics</div><h1>통합 통계</h1><p class="muted">조회·공유·신청 성과 · 보관기간 <?=$retentionDays?>일</p></div><a class="button secondary" href="/admin/analytics/export?from=<?=View::e($from)?>&to=<?=View::e($to)?>">CSV 내보내기</a></div>
<form class="panel filter-form"><label>시작<input type="date" name="from" min="<?=View::e($earliest)?>" value="<?=View::e($from)?>"></label><label>종료<input type="date" name="to" max="<?=date('Y-m-d')?>" value="<?=View::e($to)?>"></label><div class="filter-actions"><button class="primary">적용</button></div></form>
<div class="cards"><?php foreach(['views'=>'조회','shares'=>'공유','applications'=>'신청'] as $k=>$n):?><div class="card"><span><?=$n?> · 이전 대비</span><strong><?=number_format((int)$summary[$k])?></strong><small><?=$delta((int)$summary[$k],(int)$previous[$k])?></small></div><?php endforeach?><div class="card"><span>신청 전환율</span><strong><?=$rate((int)$summary['applications'],(int)$summary['views'])?></strong></div></div>
<?php foreach(['주별'=>$weekly,'월별'=>$monthly] as $heading=>$rows):?><section class="panel"><h2><?=$heading?> 요약</h2><div class="table-wrap"><table><thead><tr><th>기간</th><th>조회</th><th>공유</th><th>신청</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=View::e($r['period_label'])?></td><td><?=number_format((int)$r['views'])?></td><td><?=number_format((int)$r['shares'])?></td><td><?=number_format((int)$r['applications'])?></td></tr><?php endforeach?></tbody></table></div></section><?php endforeach?>
<section class="panel"><h2>일별 추이</h2><div class="table-wrap"><table><thead><tr><th>날짜</th><th>조회</th><th>공유</th><th>신청</th><th>전환율</th></tr></thead><tbody><?php foreach($daily as $r):?><tr><td><?=View::e($r['stat_date'])?></td><td><?=number_format((int)$r['views'])?></td><td><?=number_format((int)$r['shares'])?></td><td><?=number_format((int)$r['applications'])?></td><td><?=$rate((int)$r['applications'],(int)$r['views'])?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="panel"><h2>인기 초대장</h2><div class="table-wrap"><table><thead><tr><th>초대장</th><th>조회</th><th>공유</th><th>신청</th><th>전환율</th></tr></thead><tbody><?php foreach($popular as $r):?><tr><td><a href="/admin/invitations/<?=$r['id']?>/stats"><?=View::e($r['title'])?></a></td><td><?=number_format((int)$r['views'])?></td><td><?=number_format((int)$r['shares'])?></td><td><?=number_format((int)$r['applications'])?></td><td><?=$rate((int)$r['applications'],(int)$r['views'])?></td></tr><?php endforeach?></tbody></table></div></section>
